import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { io } from 'socket.io-client';
import { Activity, AlertTriangle, Brain, CheckCircle2, Clock3, ExternalLink, Eye, Filter, Layers3, MessageCircle, Pause, Pin, PinOff, Play, Plus, Radio, RefreshCw, Search, Settings, SlidersHorizontal, Sparkles, Star, StarOff, TestTube2, Trash2, UserRound, Users, X } from 'lucide-react';
import { API, authFetch, TOKEN_KEY, USER_KEY } from '@/utils/api';
import { useToast } from '@/components/ui/ToastProvider';
import { useDebouncedValue, isAbortError } from '@/hooks/useDebouncedValue';

type SmartResult = { id:string; rule_id:string; rule_name?:string; rule_min_score?:number|string; account_name?:string; telegram_account_id:string; chat_id:string; chat_title?:string; chat_username?:string; chat_type?:string; message_id:string; sender_id?:string; sender_username?:string; sender_name?:string; message_text:string; context?:any; match_score?:number|string|null; is_match:boolean; reason?:string; ai_status?:string; ai_error?:string|null; status:string; blocked_user_active?:boolean; blocked_group_active?:boolean; is_saved:boolean; is_pinned:boolean; deleted_in_telegram?:boolean; message_timestamp?:string; detected_at?:string; message_link?:string|null };
type SmartRule = { id:string; name:string; description?:string; instructions:string; match_mode:string; min_score:number; priority:string; account_ids:any; is_active:boolean };
type Account = { id:string; name:string; username?:string; phone_number?:string; status:string; last_activity_at?:string };

const json = async (res:Response) => { const body = await res.json().catch(() => ({})); if (!res.ok || body.success === false) throw new Error(body.error || 'حدث خطأ'); return body; };
const score = (value:any) => Math.max(0, Math.min(100, Number(value) || 0));
const scoreTone = (value:any) => score(value) >= 85 ? 'text-emerald-300 bg-emerald-500/10 border-emerald-400/30' : score(value) >= 70 ? 'text-amber-300 bg-amber-500/10 border-amber-400/30' : score(value) >= 40 ? 'text-orange-300 bg-orange-500/10 border-orange-400/30' : 'text-rose-300 bg-rose-500/10 border-rose-400/30';
const dateTime = (value?:string) => value ? new Date(value).toLocaleString('ar-EG', { dateStyle:'medium', timeStyle:'short' }) : 'غير متوفر'; const dateOnly = (value?:string) => value ? new Date(value).toLocaleDateString('ar-EG', { dateStyle:'medium' }) : 'غير متوفر'; const timeOnly = (value?:string) => value ? new Date(value).toLocaleTimeString('ar-EG', { hour:'2-digit', minute:'2-digit' }) : 'غير متوفر';
const accountIds = (value:any):string[] => Array.isArray(value) ? value.map(String) : [];

export default function TelegramSmartConversationsView({ userId }: { userId:string }) {
  const { addToast } = useToast();
  const notify = useCallback((title:string, type:'success'|'error'|'warning'|'info'='info') => addToast({ title, type }), [addToast]);
  const [accounts, setAccounts] = useState<Account[]>([]);
  const [rules, setRules] = useState<SmartRule[]>([]);
  const [results, setResults] = useState<SmartResult[]>([]);
  const [logs, setLogs] = useState<any[]>([]);
  const [notifications, setNotifications] = useState<any[]>([]);
  const [system, setSystem] = useState<any>({ status:'degraded', activeRules:0, linkedAccounts:0, accountsRunningRules:0, lastProcessedAt:null, lastConversation:null, errors:0 });
  const [stats, setStats] = useState<any>({ discovered:0, matched:0, new_count:0, saved:0, deleted:0, review:0 });
  const [monitoring, setMonitoring] = useState<any>({ activeAccounts:0, totalAccounts:0, aiOnline:true });
  const [gemini, setGemini] = useState<any>({ status:'unconfigured', configured:false, enabled:false, model:'gemini-2.5-flash', requests:0, successful:0, failed:0, averageLatencyMs:0 });
  const [settings, setSettings] = useState<any>({ enabled:true, default_min_score:70, context_before:2, context_after:2, analysis_language:'ar', retention_days:90 });
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [search, setSearch] = useState('');
  const debouncedSearch = useDebouncedValue(search.trim(), 350);
  const loadInFlightRef = React.useRef(false);
  const loadVersionRef = React.useRef(0);
  const [accountFilter, setAccountFilter] = useState('');
  const [ruleFilter, setRuleFilter] = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  const [minScore, setMinScore] = useState('');
  const [pinnedOnly, setPinnedOnly] = useState(false);
  const [savedOnly, setSavedOnly] = useState(false);
  const [ruleModal, setRuleModal] = useState(false);
  const [testModal, setTestModal] = useState(false);
  const [settingsModal, setSettingsModal] = useState(false);
  const [details, setDetails] = useState<SmartResult|null>(null);
  const [busyId, setBusyId] = useState<string|null>(null);
  const [ruleForm, setRuleForm] = useState({ name:'', description:'', instructions:'', min_score:70, match_mode:'balanced', priority:'medium', account_ids:[] as string[], is_active:true });
  const [testForm, setTestForm] = useState({ instructions:'', text:'', min_score:70, match_mode:'balanced' });
  const [testResult, setTestResult] = useState<any>(null);

  const load = useCallback(async (silent=false, signal?: AbortSignal) => {
    if (signal?.aborted || loadInFlightRef.current) return;
    loadInFlightRef.current = true;
    const requestVersion = loadVersionRef.current;
    if (!silent) setLoading(true); else setRefreshing(true);
    try {
      const query = new URLSearchParams({ limit:'50' });
      if (debouncedSearch) query.set('search', debouncedSearch);
      if (accountFilter) query.set('account_id', accountFilter);
      if (ruleFilter) query.set('rule_id', ruleFilter);
      if (statusFilter) query.set('status', statusFilter);
      if (minScore) query.set('min_score', minScore);
      if (pinnedOnly) query.set('pinned', 'true');
      if (savedOnly) query.set('saved', 'true');
      const data = await json(await authFetch(`${API}/telegram-smart-conversations/dashboard?${query.toString()}`, { signal }));
      // حالة Gemini اختيارية؛ لا تجعل فشلها يحجب بيانات المحادثات نفسها.
      const aiStatus = await json(await authFetch(`${API}/telegram-smart-conversations/ai/status`, { signal })).catch(() => ({}));
      if (requestVersion !== loadVersionRef.current) return;
      setGemini(aiStatus || {});
      setAccounts(data.accounts || []); setRules(data.rules || []); setResults(data.results || []); setLogs(data.logs || []); setNotifications(data.notifications || []); setSystem(data.system || {}); setStats(data.stats || {}); setMonitoring(data.monitoring || {}); setSettings(data.settings || settings);
    } catch (error:any) {
      if (!isAbortError(error)) notify(error.message || 'تعذر تحميل المحادثات الذكية، تحقق من اتصال الخادم', 'error');
    } finally {
      loadInFlightRef.current = false;
      if (!signal?.aborted) { setLoading(false); setRefreshing(false); }
    }
  }, [accountFilter, debouncedSearch, minScore, notify, pinnedOnly, ruleFilter, savedOnly, statusFilter]);

  useEffect(() => {
    const controller = new AbortController();
    load(false, controller.signal);
    const timer = window.setInterval(() => load(true, controller.signal), 15000);
    const socket = io(window.location.origin, { path:'/socket.io', transports:['websocket','polling'], reconnection:true });
    const user = JSON.parse(localStorage.getItem(USER_KEY) || '{}');
    const join = () => socket.emit('join_user', { userId:user.id || userId, token:localStorage.getItem(TOKEN_KEY) || '' });
    socket.on('connect', join);
    socket.on('telegram:smart:analyzed', () => load(true, controller.signal));
    socket.on('telegram:smart:high_priority', (event:any) => { const item = event?.notification; if (item) { notify(`🔴 أولوية عالية — ${item.rule_name || 'قاعدة ذكية'} (${score(item.match_score)}%)`, 'warning'); setNotifications(current => [item, ...current.filter(existing => existing.id !== item.id)].slice(0, 30)); } load(true, controller.signal); });
    return () => { controller.abort(); window.clearInterval(timer); socket.disconnect(); };
  }, [load, notify, userId]);

  const saveRule = async () => { try { await json(await authFetch(`${API}/telegram-smart-conversations/rules`, { method:'POST', body:JSON.stringify(ruleForm) })); notify('تم إنشاء القاعدة الذكية', 'success'); setRuleModal(false); setRuleForm({ name:'', description:'', instructions:'', min_score:70, match_mode:'balanced', priority:'medium', account_ids:[], is_active:true }); await load(); } catch (error:any) { notify(error.message || 'تعذر إنشاء القاعدة', 'error'); } };
  const testRule = async () => { try { const data = await json(await authFetch(`${API}/telegram-smart-conversations/test`, { method:'POST', body:JSON.stringify(testForm) })); setTestResult(data); } catch (error:any) { notify(error.message || 'تعذر اختبار القاعدة', 'error'); } };
  const testGemini = async () => { try { const data = await json(await authFetch(`${API}/telegram-smart-conversations/ai/test`, { method:'POST', body:JSON.stringify({ text:testForm.text || 'أحتاج مساعدة في إعداد بحث جامعي', instructions:testForm.instructions || 'اكتشف طلبات المساعدة الأكاديمية' }) })); setTestResult({ ...data, engine:'gemini' }); setGemini((current:any) => ({ ...current, status:'healthy', successful:(current.successful || 0) + 1 })); notify('نجح اختبار Gemini الحقيقي', 'success'); } catch (error:any) { notify(error.message || 'فشل اختبار Gemini الحقيقي', 'error'); setGemini((current:any) => ({ ...current, status:'unhealthy' })); } };
  const toggleRule = async (rule:SmartRule) => { try { await json(await authFetch(`${API}/telegram-smart-conversations/rules/${rule.id}/status`, { method:'PATCH', body:JSON.stringify({ is_active:!rule.is_active }) })); notify(rule.is_active ? 'تم إيقاف القاعدة' : 'تم تفعيل القاعدة', 'success'); await load(true); } catch (error:any) { notify(error.message || 'تعذر تغيير حالة القاعدة', 'error'); } };
  const deleteRule = async (rule:SmartRule) => { if (!window.confirm(`حذف القاعدة «${rule.name}»؟`)) return; try { await json(await authFetch(`${API}/telegram-smart-conversations/rules/${rule.id}`, { method:'DELETE' })); notify('تم حذف القاعدة', 'success'); await load(true); } catch (error:any) { notify(error.message || 'تعذر حذف القاعدة', 'error'); } };
  const updateResult = async (result:SmartResult, patch:any) => { if (busyId) return; setBusyId(result.id); try { await json(await authFetch(`${API}/telegram-smart-conversations/results/${result.id}`, { method:'PATCH', body:JSON.stringify(patch) })); await load(true); if (details?.id === result.id) setDetails({ ...details, ...patch }); } catch (error:any) { notify(error.message || 'تعذر تحديث المحادثة', 'error'); } finally { setBusyId(null); } };
  const blockUser = async (result:SmartResult) => { if (!result.sender_id) { notify('لا يتوفر معرف Telegram موثوق لهذا المستخدم', 'error'); return; } if (!window.confirm(`حظر المستخدم ${result.sender_username ? `@${result.sender_username.replace(/^@/, '')}` : result.sender_name || result.sender_id} من النتائج؟`)) return; try { await json(await authFetch(`${API}/telegram-smart-conversations/results/${result.id}/block-user`, { method:'POST', body:JSON.stringify({ reason:'حظر من المحادثات الذكية' }) })); notify('تم حظر المستخدم وإخفاء نتائجه', 'success'); setDetails(null); await load(true); } catch (error:any) { notify(error.message || 'تعذر حظر المستخدم', 'error'); } };
  const blockGroup = async (result:SmartResult) => { if (!result.chat_id) { notify('لا يتوفر Telegram Chat ID موثوق لهذه المجموعة', 'error'); return; } if (!window.confirm(`حظر المجموعة «${result.chat_title || result.chat_username || result.chat_id}»؟\nسيتم إيقاف جلب وتحليل رسائلها الجديدة.`)) return; try { await json(await authFetch(`${API}/telegram-smart-conversations/results/${result.id}/block-group`, { method:'POST', body:JSON.stringify({ reason:'حظر من المحادثات الذكية' }) })); notify('تم حظر المجموعة وإيقاف معالجتها', 'success'); await load(true); } catch (error:any) { notify(error.message || 'تعذر حظر المجموعة', 'error'); } };
  const unblockGroup = async (result:SmartResult) => { if (!result.chat_id) return; if (!window.confirm('إلغاء حظر المجموعة والسماح بمعالجة رسائلها الجديدة؟')) return; try { await json(await authFetch(`${API}/telegram-smart-conversations/blocked-groups/${encodeURIComponent(result.chat_id)}/unblock`, { method:'POST' })); notify('تم إلغاء حظر المجموعة', 'success'); await load(true); } catch (error:any) { notify(error.message || 'تعذر إلغاء حظر المجموعة', 'error'); } };
  const unblockUser = async (result:SmartResult) => { if (!result.sender_id) return; if (!window.confirm('إلغاء حظر هذا المستخدم والسماح بمعالجة رسائله الجديدة؟')) return; try { await json(await authFetch(`${API}/telegram-smart-conversations/blocked-users/${encodeURIComponent(result.sender_id)}/unblock`, { method:'POST' })); notify('تم إلغاء حظر المستخدم', 'success'); await load(true); } catch (error:any) { notify(error.message || 'تعذر إلغاء حظر المستخدم', 'error'); } };
  const ignoreMessage = async (result:SmartResult) => { try { await json(await authFetch(`${API}/telegram-smart-conversations/results/${result.id}/ignore`, { method:'POST' })); notify('تم تجاهل الرسالة', 'success'); await load(true); } catch (error:any) { notify(error.message || 'تعذر تجاهل الرسالة', 'error'); } };
  const openMessage = async (result:SmartResult) => { try { const data = await json(await authFetch(`${API}/telegram-smart-conversations/results/${result.id}/open`, { method:'POST' })); if (data.message_link) window.open(data.message_link, '_blank', 'noopener,noreferrer'); } catch (error:any) { notify(error.message || 'تعذر فتح الرسالة', 'error'); } };
  const deleteTelegramMessage = async (result:SmartResult) => { if (!window.confirm('حذف الرسالة من Telegram؟\nيتطلب ذلك صلاحية الحساب المصدر وقد لا يكون قابلًا للتراجع.')) return; try { await json(await authFetch(`${API}/telegram-smart-conversations/results/${result.id}/delete-message`, { method:'POST' })); notify('تم حذف الرسالة من Telegram', 'success'); await load(true); } catch (error:any) { notify(error.message || 'تعذر حذف الرسالة من Telegram', 'error'); } };
  const openPrivateChat = async (result:SmartResult) => { try { const data = await json(await authFetch(`${API}/telegram-smart-conversations/results/${result.id}/open-private`, { method:'POST' })); if (data.direct_link) window.open(data.direct_link, '_blank', 'noopener,noreferrer'); } catch (error:any) { notify(error.message || 'تعذر فتح المحادثة الخاصة', 'error'); } };
  const removeResult = async (result:SmartResult) => { if (!window.confirm('حذف هذه النتيجة من لوحة المحادثات الذكية؟')) return; try { await json(await authFetch(`${API}/telegram-smart-conversations/results/${result.id}`, { method:'DELETE' })); notify('تم حذف النتيجة', 'success'); setDetails(null); await load(true); } catch (error:any) { notify(error.message || 'تعذر حذف النتيجة', 'error'); } };
  const markNotificationRead = async (notification:any) => { if (notification.is_read) return; try { await json(await authFetch(`${API}/telegram-smart-conversations/notifications/${notification.id}/read`, { method:'PATCH' })); setNotifications(current => current.map(item => item.id === notification.id ? { ...item, is_read:true } : item)); } catch (error:any) { notify(error.message || 'تعذر تحديث الإشعار', 'error'); } };
  const markAllNotificationsRead = async () => { try { await json(await authFetch(`${API}/telegram-smart-conversations/notifications/read-all`, { method:'PATCH' })); setNotifications(current => current.map(item => ({ ...item, is_read:true }))); notify('تم تعليم جميع الإشعارات كمقروءة', 'success'); } catch (error:any) { notify(error.message || 'تعذر تحديث الإشعارات', 'error'); } };
  const saveSettings = async () => {
    loadVersionRef.current += 1;
    try {
      const saved = await json(await authFetch(`${API}/telegram-smart-conversations/settings`, { method:'PATCH', body:JSON.stringify(settings) }));
      // يعتمد النموذج على الصف الذي أعاده الخادم، لا على الحالة المحلية فقط.
      setSettings(current => ({ ...current, ...(saved || {}) }));
      setMonitoring(current => ({ ...current, aiOnline: saved?.enabled !== false }));
      notify('تم حفظ إعدادات الذكاء الاصطناعي واعتمادها', 'success');
      setSettingsModal(false);
      await load(true);
    } catch (error:any) {
      notify(error.message || 'تعذر حفظ الإعدادات، حاول مرة أخرى', 'error');
    }
  };
  const toggleMonitoring = async () => {
    const next = settings.enabled === false;
    loadVersionRef.current += 1;
    setSettings((current:any) => ({ ...current, enabled:next }));
    try {
      const saved = await json(await authFetch(`${API}/telegram-smart-conversations/settings`, { method:'PATCH', body:JSON.stringify({ ...settings, enabled:next }) }));
      setSettings(current => ({ ...current, ...(saved || {}), enabled: saved?.enabled ?? next }));
      setMonitoring(current => ({ ...current, aiOnline:saved?.enabled !== false }));
      notify(next ? 'تم تشغيل المراقبة الذكية واعتمادها' : 'تم إيقاف المراقبة الذكية واعتمادها', 'success');
    } catch (error:any) {
      setSettings((current:any) => ({ ...current, enabled:!next }));
      notify(error.message || 'تعذر تغيير حالة المراقبة', 'error');
    }
  };
  const visibleResults = useMemo(() => results.filter(item => ['pending','processing','retrying'].includes(String(item.ai_status || '')) || item.is_match || score(item.match_score) >= Number(minScore || 0)), [minScore, results]);
  const systemStatus = system.status || 'degraded';
  const systemStatusLabel = systemStatus === 'running' ? 'النظام يعمل' : systemStatus === 'stopped' ? 'النظام متوقف' : 'يعمل مع وجود أخطاء';
  const systemStatusClass = systemStatus === 'running' ? 'text-emerald-300 bg-emerald-500/10 border-emerald-400/30' : systemStatus === 'stopped' ? 'text-rose-300 bg-rose-500/10 border-rose-400/30' : 'text-amber-300 bg-amber-500/10 border-amber-400/30';
  const unreadNotifications = notifications.filter(item => !item.is_read).length;

  return <div dir="rtl" className="space-y-6 pb-12">
    <header className="rounded-3xl border border-violet-400/20 bg-gradient-to-br from-violet-950/60 via-[var(--bg-card)] to-sky-950/40 p-5 shadow-xl shadow-violet-950/10">
      <div className="flex flex-col xl:flex-row xl:items-center justify-between gap-5"><div className="flex items-center gap-4"><div className="w-14 h-14 rounded-2xl bg-gradient-to-br from-violet-500 to-sky-500 flex items-center justify-center text-white shadow-lg shadow-violet-500/20"><Brain size={30}/></div><div><div className="flex items-center gap-3 flex-wrap"><h1 className="text-2xl font-bold">المحادثات الذكية</h1><span className={`inline-flex items-center gap-1 rounded-full px-3 py-1 text-xs font-semibold ${monitoring.aiOnline ? 'bg-emerald-500/15 text-emerald-300' : 'bg-rose-500/15 text-rose-300'}`}><span className="w-2 h-2 rounded-full bg-current"/> {gemini.enabled && gemini.configured ? 'Gemini يعمل' : monitoring.aiOnline ? 'المحلل المحلي يعمل' : 'المحلل متوقف'}</span></div><p className="mt-1 text-sm text-[var(--text-muted)]">تحليل الرسائل الواردة من حسابات Telegram المصرح لها عبر Gemini عند تهيئته، أو المحلل المحلي عند عدم التهيئة.</p></div></div><div className="flex flex-wrap gap-2"><button onClick={toggleMonitoring} className={`px-4 py-2 rounded-xl border text-sm flex items-center gap-2 ${monitoring.aiOnline ? 'border-amber-400/30 text-amber-300' : 'border-emerald-400/30 text-emerald-300'}`}><Radio size={16}/>{monitoring.aiOnline ? 'إيقاف المراقبة' : 'تشغيل المراقبة'}</button><button onClick={() => load(true)} className="px-4 py-2 rounded-xl border border-[var(--border-default)] flex items-center gap-2 text-sm"><RefreshCw size={16} className={refreshing ? 'animate-spin' : ''}/> تحديث</button><button onClick={() => setSettingsModal(true)} className="px-4 py-2 rounded-xl border border-[var(--border-default)] flex items-center gap-2 text-sm"><Settings size={16}/> الإعدادات</button><button onClick={() => setRuleModal(true)} className="px-4 py-2 rounded-xl bg-violet-600 hover:bg-violet-500 text-white flex items-center gap-2 text-sm"><Plus size={17}/> إضافة قاعدة ذكية</button></div></div>
    </header>

    <section className="rounded-2xl border border-[var(--border-default)] bg-[var(--bg-card)] p-5"><div className="flex flex-wrap items-center justify-between gap-4"><div><h2 className="font-bold flex items-center gap-2"><Brain size={19} className="text-violet-300"/> Gemini AI</h2><p className="text-xs text-[var(--text-muted)] mt-1">حالة الاتصال المعروضة هنا من Backend، وليست حالة واجهة محلية.</p></div><div className="flex items-center gap-2"><span className={`rounded-full px-3 py-1.5 text-xs font-semibold ${gemini.status === 'healthy' ? 'bg-emerald-500/15 text-emerald-300' : gemini.status === 'unhealthy' ? 'bg-rose-500/15 text-rose-300' : 'bg-amber-500/15 text-amber-300'}`}>{gemini.status === 'healthy' ? 'متصل ويعمل' : gemini.status === 'unhealthy' ? 'غير متصل' : 'غير مهيأ'}</span><button onClick={testGemini} className="px-3 py-1.5 rounded-xl border border-violet-400/30 text-violet-200 text-xs flex items-center gap-2"><TestTube2 size={15}/> اختبار Gemini الحقيقي</button></div></div><div className="grid grid-cols-2 md:grid-cols-5 gap-3 mt-4"><MonitorMetric label="النموذج" value={gemini.model || 'غير محدد'}/><MonitorMetric label="إجمالي الطلبات" value={gemini.requests || 0}/><MonitorMetric label="الناجحة" value={gemini.successful || 0}/><MonitorMetric label="الفاشلة" value={gemini.failed || 0}/><MonitorMetric label="متوسط الاستجابة" value={`${gemini.averageLatencyMs || 0} ms`}/></div></section>

    <section className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-6 gap-3">{[['المحادثات المكتشفة',stats.discovered,MessageCircle,'text-sky-300'],['المحادثات المطابقة',stats.matched,Sparkles,'text-violet-300'],['الجديدة',stats.new_count,Layers3,'text-amber-300'],['المحفوظة',stats.saved,Star,'text-yellow-300'],['المحذوفة',stats.deleted,Trash2,'text-rose-300'],['قيد المراجعة',stats.review,Eye,'text-emerald-300']].map(([label,value,Icon,color]:any) => <div key={label} className="rounded-2xl border border-[var(--border-default)] bg-[var(--bg-card)] p-4"><div className="flex items-center justify-between"><Icon size={19} className={color}/><span className="text-2xl font-bold">{value ?? 0}</span></div><p className="mt-3 text-xs text-[var(--text-muted)]">{label}</p></div>)}</section>

    <section className="grid xl:grid-cols-[1fr_1.2fr] gap-5"><div className="rounded-2xl border border-[var(--border-default)] bg-[var(--bg-card)] p-5"><div className="flex items-start justify-between gap-3 mb-5"><div><h2 className="font-bold flex items-center gap-2"><Brain size={19} className="text-violet-300"/> 🧠 حالة المحادثات الذكية</h2><p className="text-xs text-[var(--text-muted)] mt-1">المعالجة تعمل على الخادم ولا تعتمد على بقاء Dashboard مفتوحة.</p></div><span className={`inline-flex items-center gap-2 rounded-full border px-3 py-1.5 text-xs font-semibold ${systemStatusClass}`}><span className="w-2 h-2 rounded-full bg-current"/>{systemStatusLabel}</span></div><div className="grid grid-cols-2 gap-3"><MonitorMetric label="القواعد المفعلة" value={system.activeRules || 0}/><MonitorMetric label="الحسابات المرتبطة" value={system.linkedAccounts || accounts.length}/><MonitorMetric label="تعمل عليها القواعد" value={system.accountsRunningRules || 0}/><MonitorMetric label="الأخطاء الحالية" value={system.errors || 0}/></div><div className="mt-4 rounded-xl bg-[var(--bg-elevated)] p-3"><p className="text-xs text-[var(--text-muted)]">آخر معالجة</p><p className="text-sm mt-1">{system.lastProcessedAt ? dateTime(system.lastProcessedAt) : 'لم تتم معالجة رسالة بعد'}</p><p className="text-xs text-[var(--text-muted)] mt-3">آخر محادثة</p><p className="text-sm mt-1 truncate">{system.lastConversation ? `${system.lastConversation.chat_title || system.lastConversation.chat_username || system.lastConversation.chat_id || 'محادثة'} — ${String(system.lastConversation.message_text || '').slice(0, 90)}` : 'بانتظار الرسائل الجديدة'}</p></div></div><div className="rounded-2xl border border-rose-400/20 bg-[var(--bg-card)] p-5"><div className="flex items-start justify-between gap-3 mb-4"><div><h2 className="font-bold flex items-center gap-2 text-rose-200"><AlertTriangle size={19}/> 🔔 إشعارات الأولوية العالية</h2><p className="text-xs text-[var(--text-muted)] mt-1">محفوظة حتى عند إغلاق المتصفح أو عدم وجود المستخدم داخل Dashboard.</p></div><div className="flex items-center gap-2"><span className="rounded-full bg-rose-500/15 px-2.5 py-1 text-xs text-rose-300">{unreadNotifications} غير مقروء</span><button onClick={markAllNotificationsRead} className="text-xs text-[var(--text-muted)] hover:text-[var(--text-primary)]">قراءة الكل</button></div></div><div className="space-y-2 max-h-72 overflow-auto">{notifications.slice(0,8).map(notification => <button key={notification.id} onClick={() => markNotificationRead(notification)} className={`w-full text-right rounded-xl border p-3 transition-colors ${notification.is_read ? 'border-[var(--border-default)] bg-[var(--bg-elevated)]' : 'border-rose-400/40 bg-rose-500/10'}`}><div className="flex items-center justify-between gap-3"><span className="font-semibold text-sm text-rose-200">🔴 أولوية عالية — {notification.rule_name || 'قاعدة ذكية'}</span><span className="text-[10px] text-[var(--text-muted)]">{dateTime(notification.created_at)}</span></div><p className="text-xs mt-2 text-[var(--text-secondary)]">👤 {notification.sender_username ? `@${String(notification.sender_username).replace(/^@/, '')}` : notification.sender_name || 'مستخدم غير معروف'} · 👥 {notification.chat_title || 'مجموعة غير معروفة'}</p><p className="text-xs mt-1 text-[var(--text-muted)] line-clamp-2">{notification.message_excerpt || 'تم اكتشاف محادثة ذات أولوية عالية.'}</p><p className="text-xs mt-2 text-rose-300">🎯 المطابقة: {score(notification.match_score)}%</p></button>)}{!notifications.length && <div className="py-10 text-center text-sm text-[var(--text-muted)]">لا توجد إشعارات أولوية عالية حاليًا.</div>}</div></div></section>

    <section className="grid lg:grid-cols-[1fr_1.4fr] gap-5"><div className="rounded-2xl border border-[var(--border-default)] bg-[var(--bg-card)] p-5"><div className="flex items-center justify-between mb-4"><h2 className="font-bold flex items-center gap-2"><Activity size={18} className="text-emerald-300"/> حالة المراقبة</h2><span className="text-xs text-[var(--text-muted)]">آخر مزامنة تلقائية كل 15 ثانية</span></div><div className="grid grid-cols-2 gap-3"><MonitorMetric label="الحسابات النشطة" value={`${monitoring.activeAccounts || 0}/${monitoring.totalAccounts || accounts.length}`} /><MonitorMetric label="القواعد الفعالة" value={rules.filter(rule => rule.is_active).length} /><MonitorMetric label="المحرك" value={gemini.enabled && gemini.configured ? 'Gemini' : 'محلل محلي'}/><MonitorMetric label="آخر تحليل" value={logs[0]?.created_at ? dateTime(logs[0].created_at) : 'بانتظار الرسائل'} /></div></div><div className="rounded-2xl border border-[var(--border-default)] bg-[var(--bg-card)] p-5"><div className="flex items-center justify-between mb-4"><h2 className="font-bold flex items-center gap-2"><Users size={18} className="text-sky-300"/> حسابات Telegram المرتبطة</h2><span className="text-xs text-[var(--text-muted)]">{accounts.length} حساب</span></div><div className="grid sm:grid-cols-2 xl:grid-cols-3 gap-3">{accounts.map(account => <div key={account.id} className="rounded-xl border border-[var(--border-default)] bg-[var(--bg-elevated)] p-3"><div className="flex items-start justify-between gap-2"><div className="min-w-0"><p className="font-semibold truncate">{account.name}</p><p className="text-xs text-[var(--text-muted)] truncate">{account.username ? `@${account.username.replace(/^@/, '')}` : account.phone_number || 'هوية غير متاحة'}</p></div><span className={`w-2.5 h-2.5 rounded-full mt-1.5 ${account.status === 'connected' ? 'bg-emerald-400' : 'bg-rose-400'}`}/></div><p className="text-[11px] text-[var(--text-muted)] mt-3">{account.status === 'connected' ? 'متصل وقابل للمراقبة' : 'غير متصل'}</p></div>)}{!accounts.length && <p className="text-sm text-[var(--text-muted)]">أضف حساب Telegram أولًا ليظهر هنا.</p>}</div></div></section>

    <section className="rounded-2xl border border-[var(--border-default)] bg-[var(--bg-card)] p-5"><div className="flex flex-col xl:flex-row xl:items-center justify-between gap-3 mb-4"><div><h2 className="font-bold flex items-center gap-2"><Sparkles size={18} className="text-violet-300"/> القواعد الذكية</h2><p className="text-xs text-[var(--text-muted)] mt-1">تعليمات دلالية تفهم المعنى والسياق بدل الاعتماد على كلمة منفردة.</p></div><div className="flex gap-2"><button onClick={() => setTestModal(true)} className="px-3 py-2 rounded-xl border border-violet-400/30 text-violet-300 text-sm flex items-center gap-2"><TestTube2 size={16}/> اختبار قاعدة</button><button onClick={() => setRuleModal(true)} className="px-3 py-2 rounded-xl bg-violet-600 text-white text-sm flex items-center gap-2"><Plus size={16}/> إضافة</button></div></div><div className="grid md:grid-cols-2 xl:grid-cols-3 gap-3">{rules.map(rule => <div key={rule.id} className="rounded-xl border border-[var(--border-default)] p-4"><div className="flex items-start justify-between gap-2"><div><h3 className="font-semibold">{rule.name}</h3><p className="text-xs text-[var(--text-muted)] mt-1 line-clamp-2">{rule.description || rule.instructions}</p></div><span className={`text-[10px] px-2 py-1 rounded-full ${rule.is_active ? 'bg-emerald-500/10 text-emerald-300' : 'bg-slate-500/10 text-slate-400'}`}>{rule.is_active ? 'نشطة' : 'متوقفة'}</span></div><div className="flex items-center gap-2 mt-3 text-xs text-[var(--text-muted)]"><span className="rounded-lg bg-[var(--bg-elevated)] px-2 py-1">حد المطابقة {rule.min_score}%</span><span className="rounded-lg bg-[var(--bg-elevated)] px-2 py-1">{rule.priority === 'high' ? 'أولوية عالية' : rule.priority === 'low' ? 'أولوية منخفضة' : 'أولوية متوسطة'}</span></div><div className="flex gap-2 mt-4"><button onClick={() => toggleRule(rule)} className="flex-1 px-3 py-2 rounded-lg border border-[var(--border-default)] text-xs flex items-center justify-center gap-1">{rule.is_active ? <><Pause size={14}/> إيقاف</> : <><Play size={14}/> تفعيل</>}</button><button onClick={() => deleteRule(rule)} className="px-3 py-2 rounded-lg border border-rose-400/20 text-rose-300"><Trash2 size={14}/></button></div></div>)}{!rules.length && <div className="md:col-span-2 xl:col-span-3 rounded-xl border border-dashed border-[var(--border-default)] p-8 text-center text-sm text-[var(--text-muted)]">أنشئ أول قاعدة لوصف نوع المحادثات التي تريد اكتشافها.</div>}</div></section>

    <section className="rounded-2xl border border-[var(--border-default)] bg-[var(--bg-card)] p-5"><div className="flex items-center justify-between gap-3 mb-4"><div><h2 className="font-bold flex items-center gap-2"><MessageCircle size={18} className="text-sky-300"/> المحادثات المكتشفة</h2><p className="text-xs text-[var(--text-muted)] mt-1">{visibleResults.length} نتيجة ظاهرة من أصل {stats.discovered || 0}</p></div><span className="text-xs text-[var(--text-muted)]">{loading ? 'جاري التحميل...' : monitoring.aiOnline ? 'المراقبة تعمل' : 'المراقبة متوقفة'}</span></div><div className="grid md:grid-cols-2 xl:grid-cols-[1.5fr_1fr_1fr_1fr_auto] gap-2 mb-5"><div className="relative md:col-span-2 xl:col-span-1"><Search className="absolute right-3 top-3 text-[var(--text-muted)]" size={16}/><input value={search} onChange={event => setSearch(event.target.value)} placeholder="ابحث في النص أو المستخدم أو المجموعة أو القاعدة" className="w-full pr-10 pl-3 py-2.5 rounded-xl bg-[var(--bg-elevated)] border border-[var(--border-default)] text-sm"/></div><select value={accountFilter} onChange={event => setAccountFilter(event.target.value)} className="px-3 py-2 rounded-xl bg-[var(--bg-elevated)] border border-[var(--border-default)] text-sm"><option value="">كل الحسابات</option>{accounts.map(account => <option key={account.id} value={account.id}>{account.name}</option>)}</select><select value={ruleFilter} onChange={event => setRuleFilter(event.target.value)} className="px-3 py-2 rounded-xl bg-[var(--bg-elevated)] border border-[var(--border-default)] text-sm"><option value="">كل القواعد</option>{rules.map(rule => <option key={rule.id} value={rule.id}>{rule.name}</option>)}</select><select value={statusFilter} onChange={event => setStatusFilter(event.target.value)} className="px-3 py-2 rounded-xl bg-[var(--bg-elevated)] border border-[var(--border-default)] text-sm"><option value="">كل الحالات</option><option value="new">جديدة</option><option value="review">قيد المراجعة</option><option value="important">مهمة</option><option value="completed">مكتملة</option><option value="deleted">محذوفة</option></select><div className="flex gap-2"><button onClick={() => setPinnedOnly(value => !value)} className={`px-3 py-2 rounded-xl border text-sm flex items-center gap-1 ${pinnedOnly ? 'border-amber-400/40 text-amber-300 bg-amber-500/10' : 'border-[var(--border-default)]'}`} title="المثبتة فقط"><Pin size={15}/></button><button onClick={() => setSavedOnly(value => !value)} className={`px-3 py-2 rounded-xl border text-sm flex items-center gap-1 ${savedOnly ? 'border-yellow-400/40 text-yellow-300 bg-yellow-500/10' : 'border-[var(--border-default)]'}`} title="المحفوظة فقط"><Star size={15}/></button></div></div><div className="flex items-center gap-3 mb-5"><Filter size={16} className="text-[var(--text-muted)]"/><label className="text-xs text-[var(--text-muted)]">الحد الأدنى للمطابقة</label><input type="range" min="0" max="100" value={minScore || settings.default_min_score || 0} onChange={event => setMinScore(event.target.value)} className="w-40 accent-violet-500"/><span className="text-sm font-semibold text-violet-300">{minScore || settings.default_min_score || 0}%</span><button onClick={() => setMinScore('')} className="text-xs text-[var(--text-muted)] hover:text-[var(--text-primary)]">إعادة</button></div><div className="space-y-3">{visibleResults.map(result => <SmartResultCard key={result.id} result={result} busy={busyId === result.id} onDetails={() => setDetails(result)} onUpdate={patch => updateResult(result, patch)} onDelete={() => removeResult(result)} onBlock={() => blockUser(result)} onUnblock={() => unblockUser(result)} onBlockGroup={() => blockGroup(result)} onUnblockGroup={() => unblockGroup(result)} onIgnore={() => ignoreMessage(result)} onOpenMessage={() => openMessage(result)} onDeleteMessage={() => deleteTelegramMessage(result)} onOpenPrivate={() => openPrivateChat(result)}/>)}{!visibleResults.length && !loading && <div className="py-16 text-center text-[var(--text-muted)]"><Brain className="mx-auto mb-3 text-violet-300"/><p>لا توجد محادثات مطابقة للفلاتر الحالية.</p></div>}</div></section>

    <section className="rounded-2xl border border-[var(--border-default)] bg-[var(--bg-card)] p-5"><h2 className="font-bold flex items-center gap-2 mb-4"><Clock3 size={18} className="text-slate-300"/> سجل التحليل</h2><div className="space-y-2">{logs.slice(0,8).map(log => <div key={log.id} className="flex flex-col md:flex-row md:items-center justify-between gap-2 rounded-xl bg-[var(--bg-elevated)] px-3 py-2.5 text-xs"><span className="text-[var(--text-muted)]">{dateTime(log.created_at)}</span><span>{log.account_name || 'حساب Telegram'} — {log.rule_name || 'قاعدة'}</span><span className={log.decision === 'matched' ? 'text-emerald-300' : 'text-[var(--text-muted)]'}>{log.decision === 'matched' ? `مطابقة ${score(log.match_score)}%` : 'غير مطابقة'}</span></div>)}{!logs.length && <p className="text-sm text-[var(--text-muted)]">سيظهر سجل التحليل بعد وصول رسائل جديدة.</p>}</div></section>

    {ruleModal && <Modal title="إضافة قاعدة ذكية" onClose={() => setRuleModal(false)}><div className="space-y-3"><input value={ruleForm.name} onChange={event => setRuleForm({ ...ruleForm, name:event.target.value })} placeholder="اسم القاعدة، مثل: طلبات الطلاب الأكاديمية" className="w-full p-3 rounded-xl bg-[var(--bg-elevated)] border border-[var(--border-default)]"/><input value={ruleForm.description} onChange={event => setRuleForm({ ...ruleForm, description:event.target.value })} placeholder="وصف مختصر للقاعدة" className="w-full p-3 rounded-xl bg-[var(--bg-elevated)] border border-[var(--border-default)]"/><textarea value={ruleForm.instructions} onChange={event => setRuleForm({ ...ruleForm, instructions:event.target.value })} rows={5} placeholder="اكتب بالتفصيل ما الذي تريد من المحرك اكتشافه بالمعنى والسياق..." className="w-full p-3 rounded-xl bg-[var(--bg-elevated)] border border-[var(--border-default)]"/><div className="grid grid-cols-2 gap-3"><label className="text-sm">حد المطابقة: {ruleForm.min_score}%<input type="range" min="0" max="100" value={ruleForm.min_score} onChange={event => setRuleForm({ ...ruleForm, min_score:Number(event.target.value) })} className="w-full accent-violet-500"/></label><select value={ruleForm.priority} onChange={event => setRuleForm({ ...ruleForm, priority:event.target.value })} className="p-3 rounded-xl bg-[var(--bg-elevated)] border border-[var(--border-default)]"><option value="high">أولوية عالية</option><option value="medium">أولوية متوسطة</option><option value="low">أولوية منخفضة</option></select></div><div><p className="text-sm font-semibold mb-2">الحسابات المرتبطة</p><div className="grid sm:grid-cols-2 gap-2 max-h-32 overflow-auto">{accounts.map(account => <label key={account.id} className="flex items-center gap-2 rounded-lg bg-[var(--bg-elevated)] p-2 text-sm"><input type="checkbox" checked={ruleForm.account_ids.includes(account.id)} onChange={event => setRuleForm({ ...ruleForm, account_ids:event.target.checked ? [...ruleForm.account_ids, account.id] : ruleForm.account_ids.filter(id => id !== account.id) })}/>{account.name}</label>)}</div><p className="text-xs text-[var(--text-muted)] mt-2">اترك القائمة فارغة لتطبيق القاعدة على جميع الحسابات.</p></div><button onClick={saveRule} className="w-full py-3 rounded-xl bg-violet-600 text-white font-semibold">حفظ وتفعيل القاعدة</button></div></Modal>}
    {testModal && <Modal title="اختبار القاعدة قبل التفعيل" onClose={() => { setTestModal(false); setTestResult(null); }}><div className="space-y-3"><textarea value={testForm.instructions} onChange={event => setTestForm({ ...testForm, instructions:event.target.value })} rows={4} placeholder="تعليمات القاعدة" className="w-full p-3 rounded-xl bg-[var(--bg-elevated)] border border-[var(--border-default)]"/><textarea value={testForm.text} onChange={event => setTestForm({ ...testForm, text:event.target.value })} rows={4} placeholder="النص التجريبي" className="w-full p-3 rounded-xl bg-[var(--bg-elevated)] border border-[var(--border-default)]"/><button onClick={testRule} className="w-full py-3 rounded-xl bg-violet-600 text-white flex justify-center items-center gap-2"><TestTube2 size={17}/> تحليل النص</button>{testResult && <div className={`rounded-xl border p-4 ${testResult.isMatch ? 'border-emerald-400/30 bg-emerald-500/10' : 'border-rose-400/30 bg-rose-500/10'}`}><p className="font-bold">{testResult.isMatch ? 'مطابقة' : 'غير مطابقة'} — {score(testResult.score)}%</p><p className="text-sm mt-2 text-[var(--text-muted)]">{testResult.reason}</p></div>}</div></Modal>}
    {settingsModal && <Modal title="إعدادات الذكاء الاصطناعي" onClose={() => setSettingsModal(false)}><div className="space-y-4"><label className="flex items-center justify-between rounded-xl bg-[var(--bg-elevated)] p-3"><span>تفعيل التحليل الذكي</span><input type="checkbox" checked={settings.enabled !== false} onChange={event => setSettings({ ...settings, enabled:event.target.checked })}/></label><label className="block text-sm">الحد الافتراضي للمطابقة: {settings.default_min_score ?? 70}%<input type="range" min="0" max="100" value={settings.default_min_score ?? 70} onChange={event => setSettings({ ...settings, default_min_score:Number(event.target.value) })} className="w-full accent-violet-500 mt-2"/></label><div className="grid grid-cols-2 gap-3"><label className="text-sm">رسائل قبل السياق<input type="number" min="0" max="10" value={settings.context_before ?? 0} onChange={event => setSettings({ ...settings, context_before:Number(event.target.value) })} className="mt-1 w-full p-2 rounded-lg bg-[var(--bg-elevated)] border border-[var(--border-default)]"/></label><label className="text-sm">رسائل بعد السياق<input type="number" min="0" max="10" value={settings.context_after ?? 0} onChange={event => setSettings({ ...settings, context_after:Number(event.target.value) })} className="mt-1 w-full p-2 rounded-lg bg-[var(--bg-elevated)] border border-[var(--border-default)]"/></label></div><label className="text-sm">مدة الاحتفاظ بالنتائج بالأيام<input type="number" min="1" max="3650" value={settings.retention_days ?? 90} onChange={event => setSettings({ ...settings, retention_days:Number(event.target.value) })} className="mt-1 w-full p-2 rounded-lg bg-[var(--bg-elevated)] border border-[var(--border-default)]"/></label><button onClick={saveSettings} className="w-full py-3 rounded-xl bg-violet-600 text-white font-semibold">حفظ الإعدادات</button></div></Modal>}
    {details && <Modal title="تفاصيل المحادثة الذكية" onClose={() => setDetails(null)}><div className="space-y-4"><div className="flex items-center justify-between gap-3"><div><p className="font-bold">{details.chat_title || details.chat_username || details.chat_id}</p><p className="text-xs text-[var(--text-muted)]">{details.account_name} — {dateTime(details.detected_at)}</p></div><span className={`rounded-full border px-3 py-1 text-sm font-bold ${scoreTone(details.match_score)}`}>{score(details.match_score)}%</span></div><div className="rounded-xl bg-[var(--bg-elevated)] p-4"><p className="text-xs text-[var(--text-muted)] mb-2">لماذا اعتُبرت مطابقة؟</p><p className="text-sm leading-7">{details.reason || 'لا يوجد تفسير محفوظ.'}</p></div><div className="rounded-xl border border-violet-400/30 bg-violet-500/5 p-4"><p className="text-xs text-violet-300 mb-2">نص الرسالة</p><p className="whitespace-pre-wrap leading-8">{details.message_text}</p></div><div className="flex flex-wrap gap-2"><button onClick={() => updateResult(details, { status:details.status === 'review' ? 'new' : 'review' })} className="px-3 py-2 rounded-lg border border-emerald-400/30 text-emerald-300 text-sm">{details.status === 'review' ? 'إعادة للجديدة' : 'وضع قيد المراجعة'}</button>{details.message_link && <a href={details.message_link} target="_blank" rel="noreferrer" className="px-3 py-2 rounded-lg border border-sky-400/30 text-sky-300 text-sm flex items-center gap-1"><ExternalLink size={14}/> فتح في Telegram</a>}</div></div></Modal>}
  </div>;
}

function MonitorMetric({ label, value }:{ label:string; value:any }) { return <div className="rounded-xl bg-[var(--bg-elevated)] p-3"><p className="text-xs text-[var(--text-muted)]">{label}</p><p className="font-semibold mt-1 truncate">{value}</p></div>; }
function SmartResultCard({ result, busy, onDetails, onUpdate, onDelete, onBlock, onUnblock, onBlockGroup, onUnblockGroup, onIgnore, onOpenMessage, onDeleteMessage, onOpenPrivate }:{ result:SmartResult; busy:boolean; onDetails:()=>void; onUpdate:(patch:any)=>void; onDelete:()=>void; onBlock:()=>void; onUnblock:()=>void; onBlockGroup:()=>void; onUnblockGroup:()=>void; onIgnore:()=>void; onOpenMessage:()=>void; onDeleteMessage:()=>void; onOpenPrivate:()=>void }) { const aiState = String(result.ai_status || ''); const pending = ['pending','processing','retrying'].includes(aiState); const stateLabel = aiState === 'processing' ? 'جاري تحليل Gemini' : aiState === 'retrying' ? 'إعادة محاولة تحليل Gemini' : aiState === 'failed' ? 'فشل التحليل' : aiState === 'dead_letter' ? 'فشل التحليل بعد استنفاد المحاولات' : aiState === 'completed' ? 'تم التحليل' : 'بانتظار تحليل Gemini'; const stateTone = aiState === 'failed' || aiState === 'dead_letter' ? 'text-rose-300 bg-rose-500/10 border-rose-400/30' : aiState === 'processing' || aiState === 'retrying' ? 'text-sky-300 bg-sky-500/10 border-sky-400/30' : aiState === 'completed' ? 'text-emerald-300 bg-emerald-500/10 border-emerald-400/30' : 'text-amber-300 bg-amber-500/10 border-amber-400/30'; const blocked = result.status === 'blocked' || result.blocked_user_active === true; const groupBlocked = result.blocked_group_active === true; return <article className={`rounded-2xl border p-4 transition-colors ${result.is_pinned ? 'border-amber-400/40 bg-amber-500/5' : 'border-[var(--border-default)] bg-[var(--bg-elevated)]'}`}><div className="flex flex-col xl:flex-row xl:items-start justify-between gap-4"><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><span className="font-bold text-violet-300">{result.rule_name || 'قاعدة ذكية'}</span><span className={`rounded-full border px-2 py-0.5 text-xs font-semibold ${stateTone}`}>{aiState !== 'completed' ? stateLabel : `${score(result.match_score)}% ${score(result.match_score) >= 85 ? 'مطابقة قوية' : 'تم التحليل'}`}</span><span className="rounded-full border border-slate-400/20 px-2 py-0.5 text-xs text-[var(--text-muted)]">حد القاعدة: {result.rule_min_score ?? '—'}%</span>{blocked && <span className="rounded-full border border-orange-400/30 bg-orange-500/10 px-2 py-0.5 text-xs text-orange-300">🚫 المستخدم محظور</span>}{groupBlocked && <span className="rounded-full border border-orange-400/30 bg-orange-500/10 px-2 py-0.5 text-xs text-orange-300">🚫 المجموعة محظورة</span>}{result.is_pinned && <span className="text-xs text-amber-300 flex items-center gap-1"><Pin size={12}/> مثبتة</span>}{result.deleted_in_telegram && <span className="text-xs text-rose-300 flex items-center gap-1"><AlertTriangle size={12}/> محذوفة من Telegram</span>}</div><h3 className={`mt-3 font-semibold ${result.is_pinned ? 'text-amber-200' : 'text-[var(--text-primary)]'}`}>{result.chat_title || result.chat_username || result.chat_id}</h3><div className="flex flex-wrap items-center gap-3 mt-2 text-xs text-[var(--text-muted)]"><span className="flex items-center gap-1"><UserRound size={13}/>معرف المستخدم: {result.sender_id || 'غير متاح'}</span><span className="flex items-center gap-1"><Users size={13}/> {result.account_name || 'حساب Telegram'}</span><span className="flex items-center gap-1"><Clock3 size={13}/>التاريخ: {dateOnly(result.message_timestamp || result.detected_at)}</span><span className="flex items-center gap-1">الوقت: {timeOnly(result.message_timestamp || result.detected_at)}</span></div><p className="mt-3 whitespace-pre-wrap break-words leading-7 text-sm line-clamp-4">{result.message_text}</p><p className="mt-2 text-xs text-[var(--text-muted)]">{result.ai_error && (aiState === 'failed' || aiState === 'dead_letter') ? `سبب الفشل: ${result.ai_error}` : result.reason || (pending ? 'المهمة قيد المعالجة.' : 'تم تسجيل النتيجة.')}</p></div><div className="flex flex-wrap xl:flex-col gap-2 shrink-0"><button onClick={onDetails} className="px-3 py-2 rounded-lg border border-sky-400/30 text-sky-300 text-sm flex items-center gap-1"><Eye size={15}/> عرض</button><button onClick={onIgnore} disabled={busy} className="px-3 py-2 rounded-lg border border-slate-400/30 text-slate-300 text-sm flex items-center gap-1 disabled:opacity-50"><SlidersHorizontal size={15}/> تجاهل الرسالة</button><button onClick={onOpenMessage} disabled={busy || !result.message_link} className="px-3 py-2 rounded-lg border border-sky-400/30 text-sky-300 text-sm flex items-center gap-1 disabled:opacity-50"><MessageCircle size={15}/> فتح الرسالة</button><button onClick={onOpenMessage} disabled={busy || !result.message_link} className="px-3 py-2 rounded-lg border border-cyan-400/30 text-cyan-300 text-sm flex items-center gap-1 disabled:opacity-50"><ExternalLink size={15}/> الذهاب إلى المحادثة</button><button onClick={onDeleteMessage} disabled={busy || result.deleted_in_telegram} className="px-3 py-2 rounded-lg border border-rose-400/30 text-rose-300 text-sm flex items-center gap-1 disabled:opacity-50"><Trash2 size={15}/> حذف الرسالة</button><button onClick={onOpenPrivate} disabled={busy || !result.sender_id} className="px-3 py-2 rounded-lg border border-violet-400/30 text-violet-300 text-sm flex items-center gap-1 disabled:opacity-50"><MessageCircle size={15}/> محادثة خاصة</button><button onClick={() => onUpdate({ is_pinned:!result.is_pinned })} disabled={busy} className="px-3 py-2 rounded-lg border border-amber-400/30 text-amber-300 text-sm flex items-center gap-1 disabled:opacity-50">{result.is_pinned ? <><PinOff size={15}/> إلغاء التثبيت</> : <><Pin size={15}/> تثبيت</>}</button><button onClick={() => onUpdate({ is_saved:!result.is_saved })} disabled={busy} className="px-3 py-2 rounded-lg border border-yellow-400/30 text-yellow-300 text-sm flex items-center gap-1 disabled:opacity-50">{result.is_saved ? <><StarOff size={15}/> إلغاء الحفظ</> : <><Star size={15}/> حفظ</>}</button>{groupBlocked ? <button onClick={onUnblockGroup} disabled={busy || !result.chat_id} className="px-3 py-2 rounded-lg border border-emerald-400/30 text-emerald-300 text-sm flex items-center gap-1 disabled:opacity-50"><CheckCircle2 size={15}/> إلغاء حظر المجموعة</button> : <button onClick={onBlockGroup} disabled={busy || !result.chat_id} className="px-3 py-2 rounded-lg border border-orange-400/30 text-orange-300 text-sm flex items-center gap-1 disabled:opacity-50"><X size={15}/> حظر المجموعة</button>}{blocked ? <button onClick={onUnblock} disabled={busy || !result.sender_id} className="px-3 py-2 rounded-lg border border-emerald-400/30 text-emerald-300 text-sm flex items-center gap-1 disabled:opacity-50"><CheckCircle2 size={15}/> إلغاء الحظر</button> : <button onClick={onBlock} disabled={busy || !result.sender_id} className="px-3 py-2 rounded-lg border border-orange-400/30 text-orange-300 text-sm flex items-center gap-1 disabled:opacity-50"><X size={15}/> حظر المستخدم</button>}<button onClick={onDelete} className="px-3 py-2 rounded-lg border border-rose-400/30 text-rose-300 text-sm flex items-center gap-1"><Trash2 size={15}/> حذف</button></div></div></article>; }
function Modal({ title, children, onClose }:{ title:string; children:React.ReactNode; onClose:()=>void }) { return <div className="fixed inset-0 z-50 bg-black/70 flex items-center justify-center p-4"><div className="w-full max-w-2xl max-h-[90vh] overflow-auto rounded-2xl border border-[var(--border-default)] bg-[var(--bg-card)] p-5"><div className="flex items-center justify-between gap-3 mb-5"><h3 className="font-bold text-lg">{title}</h3><button onClick={onClose} className="p-1 rounded-lg hover:bg-[var(--bg-hover)]" aria-label="إغلاق"><X size={20}/></button></div>{children}</div></div>; }
